package com.exito.chop;
import android.content.Context;import android.security.keystore.*;import android.util.Base64;import java.security.KeyStore;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
final class KeyStoreSecret {
 static javax.crypto.SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);if(!s.containsAlias("exito-stability")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("exito-stability",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return(javax.crypto.SecretKey)s.getKey("exito-stability",null);}
 static void save(Context c,String secret)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String value=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(secret.trim().getBytes("UTF-8")),Base64.NO_WRAP);c.getSharedPreferences("ai-private",0).edit().putString("credential",value).apply();}
 static String get(Context c)throws Exception{String value=c.getSharedPreferences("ai-private",0).getString("credential","");if(value.isEmpty())return "";String[] p=value.split(":",2);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(p[0],Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(p[1],Base64.NO_WRAP)),"UTF-8");}
}
